ch .distance{font-size:24px;font-weight:700;margin:9px 0 0}.care-dashboard .match .distance small{font-size:12px;font-weight:400}.care-dashboard .match button{width:100%;margin-top:10px}.care-dashboard .empty{padding:30px;text-align:center;border:1px dashed #c9d6df;border-radius:10px;color:var(--muted)}.care-dashboard .request{padding:14px 0;border-bottom:1px solid var(--line)}.care-dashboard .request:last-child{border-bottom:0}.care-dashboard .request-top{display:flex;justify-content:space-between;gap:8px}.care-dashboard .actions{display:flex;gap:7px;margin-top:10px;flex-wrap:wrap}.care-dashboard .actions button{padding:7px 11px;font-size:12px}.care-dashboard .actions select{width:auto;padding:6px}.care-dashboard .hospital-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.care-dashboard .hospital{padding:17px}.care-dashboard .beds{display:flex;gap:5px;flex-wrap:wrap;margin:6px 0 12px}.care-dashboard .bed{width:23px;height:23px;border-radius:5px;border:1px solid #a2d8c1;background:#dff3e9;display:inline-flex;align-items:center;justify-content:center;font-size:10px}.care-dashboard .bed.Temporary{background:#fff2ce;border-color:#e6ca77}.care-dashboard .bed.Reserved{background:#dceaff;border-color:#a0bdeb}.care-dashboard .bed.Available{background:#dcfce7;border-color:#22c55e;color:#166534;font-weight:800}.care-dashboard .bed.Occupied{background:#fee2e2;border-color:#ef4444;color:#b91c1c;font-weight:900}.care-dashboard .legend{display:flex;gap:15px;flex-wrap:wrap;font-size:11px;color:var(--muted)}.care-dashboard .legend span{display:flex;gap:5px;align-items:center}.care-dashboard .legend .bed{width:12px;height:12px}.care-dashboard .care-row{display:flex;justify-content:space-between;font-size:12px}.care-dashboard .events{max-height:180px;overflow:auto}.care-dashboard .event{font-size:12px;padding:8px 0;border-bottom:1px solid var(--line)}.care-dashboard .event time{color:var(--muted);margin-right:8px}.care-dashboard .toast{position:fixed;bottom:2