@section('js')
<script>(() => {
const stateUrl = @json(url('/emergency/state').'?page='.$page), actionUrl = @json(url('/emergency/action'));
const page = @json($page);
const el = id => document.getElementById(id);
const esc = text => String(text ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data, selected = '', busy = false, toastTimer;
function toast(message){el('toast').textContent=message;el('toast').classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el('toast').classList.add('hidden'),6000)}
async function refresh(){try{const res=await fetch(stateUrl,{credentials:'same-origin',cache:'no-store',headers:{Accept:'application/json'}});if(!res.ok)throw Error('Server unavailable');data=await res.json();if(data.csrf_token)document.querySelector('meta[name="csrf-token"]').content=data.csrf_token;render();el('connection').textContent='● Connected · '+new Date().toLocaleTimeString()}catch(e){el('connection').textContent='Connection unavailable';toast(e.message)}}
async function act(action, payload={}){
 if(busy)return;
 busy=true;document.querySelectorAll('.care-dashboard button').forEach(b=>b.disabled=true);
 try{
  const send=()=>fetch(actionUrl,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json',Accept:'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content},body:JSON.stringify({action,...payload})});
  let res=await send();
  if(res.status===419){
   const session=await fetch(stateUrl,{credentials:'same-origin',cache:'no-store',headers:{Accept:'application/json'}});
   if(session.status===401)throw Error('Your login has expired. Sign in again; your form entries are still here.');
   if(!session.ok)throw Error('Unable to refresh your session. Refresh this page and try again.');
   const fresh=await session.json();
   document.querySelector('meta[name="csrf-token"]').content=fresh.csrf_token;
   res=await send();
  }
  if(res.status===419)throw Error('Session could not be refreshed. Sign in again and retry.');
  if(res.status===401)throw Error('Your login has expired. Sign in again.');
  const result=await res.json();
  if(!res.ok)throw Error(result.message || 'Unable to save. Please try again.');
  if(result.id)selected=result.id;
  toast(result.message);await refresh();
 }catch(e){toast(e.message)}finally{busy=false;document.querySelectorAll('.care-dashboard button').forEach(b=>b.disabled=false)}
}
function remaining(r){return r.expires_at ? Math.max(0,r.expires_at-data.now)+'s remaining' : ''}
function render(){

 if(el('metrics')) el('metrics').innerHTML=[[data.stats.requests,'Visible requests'],[data.stats.pending,'Awaiting approval'],[data.stats.reserved,'Confirmed reservations'],[data.stats.available,'Available care beds']].map(([n,t])=>`<div class="metric"><strong>${n}</strong><span>${t}</span></div>`).join('');
 if(el('operatorBadge')){el('operatorBadge').textContent=data.operator?'Hospital role verified':'Patient access';el('operatorLogin').classList.toggle('hidden',data.operator);el('operatorControls').classList.toggle('hidden',!data.operator);}
 if(!data.requests.some(r=>r.id===selected))selected=data.requests[0]?.id || '';
 if(el('selectedRequest')){el('selectedRequest').innerHTML=data.requests.length ? data.requests.map(r=>`<option value="${r.id}" ${r.id===selected?'selected':''}>${esc(r.patient)} · ${r.care} · ${r.status}</option>`).join('') : '<option>Submit a request to compare hospitals</option>';
 const r=data.requests.find(r=>r.id===selected);
 el('selectedSummary').innerHTML=r?`<p><strong>${esc(r.location)}</strong> · ${esc(r.care)} · <span class="badge ${r.priority===3?'critical':r.priority===2?'urgent':''}">${r.verified?'Verified '+r.severity:'Unverified · standard priority'}</span> <span class="badge">${r.status}</span></p>${['Pending','Reserved','Occupied'].includes(r.status)?`<div class="note">Assigned: <strong>Hospital ${esc(r.hospital_id)}</strong> · ${esc(r.bed_id)} · ${esc(remaining(r))}<br>Cards below show current remaining capacity. Your assigned bed stays with this request.</div>`:''}`:'';
 let best=false;
 el('matches').innerHTML=r?(r.matches || []).map(m=>{const recommended=m.compatible&&!best;if(recommended)best=true;const canRequest=data.profile.role!=='hospital'&&['New','Released','Expired','Rejected'].includes(r.status);return `<article class="match ${recommended?'best':''} ${!m.compatible?'rejected':''}"><div class="match-top"><h3>${m.name}</h3><span class="badge ${recommended?'good':''}">${recommended?'Recommended':m.compatible?'Compatible':'Rejected'}</span></div><div class="distance">${m.distance} <small>km · mock distance</small></div><p>${m.available} ${r.care} beds available${m.reclaimable?` · ${m.reclaimable} lower-priority hold reclaimable`:''}</p>${m.reason?`<p class="critical">${esc(m.reason)}</p>`:''}${m.compatible&&canRequest?`<button data-action="request" data-id="${r.id}" data-hospital="${m.id}">Request ${r.care==='General'?'General':r.care} Bed</button>`:''}</article>`}).join(''):'<div class="empty">Start with the accident scenario. Hospital A has no available ICU bed; Hospital C is the closest compatible option.</div>';
 }
 if(el('queue')) el('queue').innerHTML=data.requests.length?data.requests.map(r=>`<article class="request"><div class="request-top"><div><strong>${esc(r.patient)}</strong><p>${esc(r.care)} · ${r.hospital_id?'Hospital '+r.hospital_id:'No hospital requested'} · ${esc(remaining(r))}</p></div><div><span class="badge ${r.priority===3?'critical':''}">P${r.priority} · ${r.verified?r.severity:'Unverified'}</span> <span class="badge ${r.status==='Reserved'?'good':''}">${r.status}</span></div></div>${r.status==='Released'?'<p>Temporary hold reassigned for verified Critical care. Select this patient to request another hospital.</p>':''}<div class="actions">${page==='requests'?`<button class="secondary" data-select="${r.id}">View hospitals</button>`:''}${page==='approvals'&&data.operator&&['New','Pending'].includes(r.status)?`<select id="triage-${r.id}" aria-label="Verified severity for ${esc(r.patient)}">${['Critical','Urgent','Stable'].map(s=>`<option ${s===r.severity?'selected':''}>${s}</option>`).join('')}</select><button class="secondary" data-action="verify" data-id="${r.id}">${r.verified?'Update severity':'Verify severity'}</button>`:''}${page==='approvals'&&data.operator&&r.status==='Pending'?`<button data-action="accept" data-id="${r.id}">Accept → Reserved</button><button class="danger" data-action="reject" data-id="${r.id}">Reject</button>`:''}${page==='approvals'&&data.operator&&r.status==='Reserved'?`<button data-action="arrive" data-id="${r.id}">Patient arrived → Occupied</button>`:''}</div></article>`).join(''):'<div class="empty">No emergency requests yet.</div>';
 if(el('hospitals')) el('hospitals').innerHTML=data.hospitals.map(h=>`<article class="hospital"><div class="match-top"><h3>${h.name}</h3><span class="badge ${h.status==='Open'?'good':''}">${h.status==='Open'?'● Open · accepting requests':'● Offline'}</span></div><p>${h.distance} km from Accident Site</p>${['General','ICU','Ventilator'].map(c=>{const bs=h.beds.filter(b=>b.care===c);return `<div class="care-row"><strong>${c==='General'?'General Bed':c}</strong><span>${bs.filter(b=>b.status==='Available').length} available</span></div><div class="beds">${bs.map(b=>`<span class="bed ${b.status}" title="${esc(b.id)} · ${b.status}" aria-label="${esc(b.id)} ${b.status}">${b.status==='Occupied'?'×':b.status==='Reserved'?'R':b.status==='Temporary'?'T':'+'}</span>`).join('')}</div>`}).join('')}</article>`).join('');
 if(el('events')) el('events').innerHTML=data.events.length?data.events.map(e=>`<div class="event"><time>${new Date(e.at*1000).toLocaleTimeString()}</time>${esc(e.message)}</div>`).join(''):'<p>Actions and allocation decisions will appear here.</p>';
}
if(el('patientForm'))el('patientForm').addEventListener('submit',e=>{e.preventDefault();act('create',Object.fromEntries(new FormData(e.target)))});
if(el('selectedRequest'))el('selectedRequest').addEventListener('change',e=>{selected=e.target.value;render()});
if(el('demoFill'))el('demoFill').onclick=()=>{el('patient').value='Accident Patient '+String((data?.requests.length || 0)+1).padStart(2,'0');el('location').value='Accident Site';el('severity').value='Critical';el('care').value='ICU';el('patientForm').scrollIntoView({behavior:'smooth',block:'center'})};
if(el('reset'))el('reset').onclick=()=>{if(confirm('Reset only the seeded emergency demo data?'))act('reset')};
document.addEventListener('click',e=>{const select=e.target.closest('[data-select]');if(select){selected=select.dataset.select;render();el('selectedRequest').scrollIntoView({behavior:'smooth'});return}const b=e.target.closest('[data-action]');if(!b)return;const payload={id:b.dataset.id};if(b.dataset.hospital)payload.hospital_id=b.dataset.hospital;if(b.dataset.action==='verify')payload.severity=el('triage-'+payload.id).value;act(b.dataset.action,payload)});
function revealSection(){const target=document.getElementById(location.hash.slice(1));const section=target?.closest('details');if(section)section.open=true;}
window.addEventListener('hashchange',revealSection);revealSection();
refresh();setInterval(()=>{if(!busy && !document.hidden && !document.activeElement?.id?.startsWith('triage-'))refresh()},5000);
})();</script>
@endsection
